import type { HTMLAttributes } from 'react';
import { cn } from '../utils/cn';
import { useTheme } from './ThemeProvider';
import type { BrandPreset } from './presets';

export interface LogoProps extends HTMLAttributes<HTMLSpanElement> {
  /** Mark size in px. */
  size?: number;
  /** Show the product name next to the mark. */
  wordmark?: boolean;
  /** Override the preset from ThemeProvider. */
  brand?: BrandPreset;
}

/** The active brand's mark, optionally with its wordmark. */
export function Logo({ size = 28, wordmark = false, brand, className, ...props }: LogoProps) {
  const theme = useTheme();
  const active = brand ?? theme.brand;
  return (
    <span
      role="img"
      aria-label={active.name}
      className={cn('inline-flex items-center gap-[7px]', className)}
      {...props}
    >
      {active.mark(size)}
      {wordmark && (
        <span aria-hidden="true" className="font-sans font-bold tracking-[-0.02em] text-foreground" style={{ fontSize: Math.round(size * 0.64) }}>
          {active.name}
          <span className="text-primary">.</span>
        </span>
      )}
    </span>
  );
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState, useSyncExternalStore, type ReactNode } from 'react';
import { gntikPreset, type BrandPreset } from './presets';
import type { ResolvedTheme, ThemeMode } from './theme-script';

export { themeScript, type ThemeMode, type ResolvedTheme } from './theme-script';

/** Theme class per resolved mode. Light is the token default (:root), so it adds no class. */
const THEME_CLASS: Record<ResolvedTheme, string> = { dark: 'dark', light: '', high_contrast: 'high_contrast' };
const ALL_CLASSES = ['dark', 'high_contrast'];
const SYSTEM_QUERIES = ['(prefers-color-scheme: light)', '(prefers-contrast: more)'];

interface ThemeContextValue {
  mode: ThemeMode;
  resolved: ResolvedTheme;
  setMode: (mode: ThemeMode) => void;
  brand: BrandPreset;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

function systemTheme(): ResolvedTheme {
  if (typeof window === 'undefined' || !window.matchMedia) return 'dark';
  if (window.matchMedia('(prefers-contrast: more)').matches) return 'high_contrast';
  return window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
}

function subscribeSystem(onChange: () => void) {
  if (typeof window === 'undefined' || !window.matchMedia) return () => {};
  const queries = SYSTEM_QUERIES.map((q) => window.matchMedia(q));
  queries.forEach((q) => q.addEventListener('change', onChange));
  return () => queries.forEach((q) => q.removeEventListener('change', onChange));
}

function readStored(key: string): ThemeMode | null {
  try {
    const v = localStorage.getItem(key);
    return v === 'dark' || v === 'light' || v === 'high_contrast' || v === 'system' ? v : null;
  } catch {
    return null;
  }
}

/** Same-tab writes (the `storage` event only fires in other tabs). */
const storeListeners = new Set<() => void>();

function subscribeStored(onChange: () => void) {
  storeListeners.add(onChange);
  if (typeof window !== 'undefined') window.addEventListener('storage', onChange);
  return () => {
    storeListeners.delete(onChange);
    if (typeof window !== 'undefined') window.removeEventListener('storage', onChange);
  };
}

const serverStored = () => null;
const serverSystem = (): ResolvedTheme => 'dark';

export interface ThemeProviderProps {
  children: ReactNode;
  /** Mode when nothing is stored. Dark is the kit default. */
  defaultMode?: ThemeMode;
  /**
   * Mode for the server render and hydration (e.g. read from a cookie); defaults to `defaultMode`.
   * The stored choice, if any, applies right after hydration.
   */
  initialMode?: ThemeMode;
  /** Brand preset (name + logo). Colours are the same for every preset. */
  brand?: BrandPreset;
  /** localStorage key; pass `null` to disable persistence. */
  storageKey?: string | null;
  /** Element that receives the theme class. Defaults to <html>. */
  target?: () => HTMLElement | null;
}

/**
 * Applies the theme class to <html> (dark · light · high_contrast, or follows the OS),
 * persists the choice and exposes the brand preset. SSR-safe: the server and hydration render
 * use `initialMode ?? defaultMode`; the stored mode and the OS preference are read through
 * useSyncExternalStore, so they apply right after hydration without a mismatch. To avoid a
 * flash on load, inline `themeScript()` in the document <head>.
 */
export function ThemeProvider({
  children,
  defaultMode = 'dark',
  initialMode,
  brand = gntikPreset,
  storageKey = 'gntik-theme',
  target = () => (typeof document === 'undefined' ? null : document.documentElement),
}: ThemeProviderProps) {
  const [localMode, setLocalMode] = useState<ThemeMode>(initialMode ?? defaultMode);
  const getStored = useCallback(() => (storageKey ? readStored(storageKey) : null), [storageKey]);
  const stored = useSyncExternalStore(subscribeStored, getStored, serverStored);
  const system = useSyncExternalStore(subscribeSystem, systemTheme, serverSystem);
  const mode = stored ?? localMode;
  const resolved = mode === 'system' ? system : mode;

  useEffect(() => {
    const el = target();
    if (!el) return;
    el.classList.remove(...ALL_CLASSES);
    const cls = THEME_CLASS[resolved];
    if (cls) el.classList.add(cls);
    el.style.colorScheme = resolved === 'light' ? 'light' : 'dark';
    el.dataset.brand = brand.id;
  }, [resolved, brand.id, target]);

  const setMode = useCallback(
    (next: ThemeMode) => {
      setLocalMode(next);
      if (!storageKey) return;
      try {
        localStorage.setItem(storageKey, next);
      } catch {}
      storeListeners.forEach((l) => l());
    },
    [storageKey],
  );

  const value = useMemo(() => ({ mode, resolved, setMode, brand }), [mode, resolved, setMode, brand]);
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

/** Current theme and brand. Outside a provider it reports the dark default and the gntik preset. */
export function useTheme(): ThemeContextValue {
  return (
    useContext(ThemeContext) ?? { mode: 'dark', resolved: 'dark', setMode: () => {}, brand: gntikPreset }
  );
}

import type { ReactNode } from 'react';
import { MUSEMATIC_MARK_PATH } from './musematic-mark';

/**
 * A brand preset is a product skin: name and logo only. Colours never change
 * between presets — every product renders the frozen tokens of @gntik-ai/tokens.
 */
export interface BrandPreset {
  id: string;
  /** Product name, used in the wordmark and as the logo's accessible name. */
  name: string;
  /** Renders the square mark at `size` px. */
  mark: (size: number) => ReactNode;
}

/** Neutral default: a token-coloured monogram, no product named. */
export const gntikPreset: BrandPreset = {
  id: 'gntik',
  name: 'gntik',
  mark: (size) => (
    <svg width={size} height={size} viewBox="0 0 64 64" aria-hidden="true" className="block shrink-0">
      <rect width="64" height="64" rx="14" className="fill-chrome" />
      <path
        d="M41 24.5A11 11 0 1 0 43 32h-11"
        fill="none"
        strokeWidth="6"
        strokeLinecap="round"
        className="stroke-primary"
      />
    </svg>
  ),
};

export const musematicPreset: BrandPreset = {
  id: 'musematic',
  name: 'musematic',
  mark: (size) => (
    <svg width={size} height={size} viewBox="0 0 64 64" aria-hidden="true" className="block shrink-0">
      <rect width="64" height="64" rx="14" fill="#0C2017" />
      <svg x="9" y="9" width="46" height="46" viewBox="0 0 512 512">
        <path fill="#33CE73" fillRule="evenodd" d={MUSEMATIC_MARK_PATH} />
      </svg>
    </svg>
  ),
};

/**
 * Falcone — PLACEHOLDER until the product's logo artwork lands: a token-coloured "F" monogram.
 * Swap `mark` for the real artwork (as musematic does); the name and id stay.
 */
export const falconePreset: BrandPreset = {
  id: 'falcone',
  name: 'Falcone',
  mark: (size) => (
    <svg width={size} height={size} viewBox="0 0 64 64" aria-hidden="true" className="block shrink-0">
      <rect width="64" height="64" rx="14" className="fill-chrome" />
      <path d="M24 46V18h18M24 32h13" fill="none" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round" className="stroke-primary" />
    </svg>
  ),
};

export const presets = { gntik: gntikPreset, musematic: musematicPreset, falcone: falconePreset } as const;

/**
 * Server-safe theme helpers: no React, no 'use client'. Import from `@gntik-ai/ui/theme-script`
 * in a React Server Component (e.g. a Next.js root layout); the main entry re-exports them.
 */

export type ThemeMode = 'dark' | 'light' | 'high_contrast' | 'system';
export type ResolvedTheme = Exclude<ThemeMode, 'system'>;

/**
 * Inline script for <head> that applies the stored theme before first paint.
 * Usage: `<script dangerouslySetInnerHTML={{ __html: themeScript() }} />`.
 */
export function themeScript(storageKey = 'gntik-theme', defaultMode: ThemeMode = 'dark') {
  return `(function(){try{var m=localStorage.getItem(${JSON.stringify(storageKey)})||${JSON.stringify(defaultMode)};if(m==='system'){var q=function(s){return window.matchMedia(s).matches};m=q('(prefers-contrast: more)')?'high_contrast':q('(prefers-color-scheme: light)')?'light':'dark'}var e=document.documentElement;e.classList.remove('dark','high_contrast');if(m!=='light')e.classList.add(m);e.style.colorScheme=m==='light'?'light':'dark'}catch(_){}})();`;
}
